import 'dotenv/config';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import express from 'express';
import helmet from 'helmet';
import multer from 'multer';
import nodemailer from 'nodemailer';
import { rateLimit } from 'express-rate-limit';
import { db, transaction, logEvent, addDays, mondayOf, toISODate } from './database.mjs';
import { passwordHash, verifyPassword, createToken, readToken, tokenHash, randomToken, cookieOptions } from './security.mjs';
import { extractDocument, splitChunks, fetchReference } from './content.mjs';
import { generate, parseJsonOutput, retrieveSources, sourcesForQuery, contextBlock, citationList } from './ai.mjs';
import { planForSpace, rebuildPlan } from './planning.mjs';
import { enqueueProcessing, recoverJobs } from './worker.mjs';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const app=express();const port=Number(process.env.PORT)||3000;
const uploadDir=path.join(root,'data','uploads');fs.mkdirSync(uploadDir,{recursive:true});
app.disable('x-powered-by');
app.use(helmet({contentSecurityPolicy:{directives:{defaultSrc:["'self'"],scriptSrc:["'self'"],styleSrc:["'self'",'https://fonts.googleapis.com'],fontSrc:["'self'",'https://fonts.gstatic.com'],imgSrc:["'self'",'data:'],connectSrc:["'self'"],workerSrc:["'self'"],objectSrc:["'none'"],baseUri:["'self'"],frameAncestors:["'none'"],upgradeInsecureRequests:null}}}));
app.use(express.json({limit:'1mb'}));app.use(express.urlencoded({extended:false,limit:'1mb'}));
app.use(express.static(path.join(root,'public'),{maxAge:process.env.NODE_ENV==='production'?'1h':0,etag:true}));
const authLimiter=rateLimit({windowMs:15*60*1000,limit:12,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Muitas tentativas. Aguarde alguns minutos.'}});
const aiLimiter=rateLimit({windowMs:60*1000,limit:10,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Limite de gerações atingido. Aguarde um minuto.'}});
const allowedExt=new Set(['pdf','ppt','pptx','doc','docx','png','jpg','jpeg','webp','tif','tiff','txt','md','csv']);
const storage=multer.diskStorage({destination:uploadDir,filename:(req,file,cb)=>cb(null,`${crypto.randomUUID()}${path.extname(file.originalname).toLowerCase()}`)});
const upload=multer({storage,limits:{fileSize:25*1024*1024,files:1},fileFilter:(req,file,cb)=>{const ext=path.extname(file.originalname).slice(1).toLowerCase();if(!allowedExt.has(ext))return cb(new Error('Formato não permitido. Use PDF, PPTX, DOCX, imagens ou texto.'));cb(null,true)}});
const asyncRoute=fn=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);
const fail=(status,message,code)=>Object.assign(new Error(message),{status,code});
const safeUser=user=>({id:user.id,name:user.name,email:user.email});
const requireAuth=asyncRoute(async(req,res,next)=>{const token=req.cookies?.study_session||req.headers.authorization?.replace(/^Bearer\s+/i,'');const session=readToken(token);if(!session)throw fail(401,'Sua sessão expirou. Entre novamente.');const user=db.prepare('SELECT id,name,email FROM users WHERE id=?').get(session.uid);if(!user)throw fail(401,'Conta não encontrada.');req.user=user;next()});
// Parse the small signed cookie without another runtime dependency.
app.use((req,res,next)=>{req.cookies={};for(const item of String(req.headers.cookie||'').split(';')){const at=item.indexOf('=');if(at>0)req.cookies[item.slice(0,at).trim()]=decodeURIComponent(item.slice(at+1).trim())}next()});
function getSpace(req){const requested=Number(req.get('x-space-id')||req.query.spaceId||req.body?.spaceId);const spaces=db.prepare('SELECT * FROM spaces WHERE user_id=? ORDER BY id').all(req.user.id);if(!spaces.length)throw fail(404,'Crie um espaço de estudos para continuar.');const space=requested?spaces.find(s=>s.id===requested):spaces[0];if(!space)throw fail(404,'Espaço de estudos não encontrado.');req.space=space;return space;}
function rowInSpace(table,id,spaceId){return db.prepare(`SELECT * FROM ${table} WHERE id=? AND space_id=?`).get(Number(id),spaceId)}
function requireSpace(req,res,next){try{getSpace(req);next()}catch(error){next(error)}}
function toSafeFilename(name){return path.basename(String(name||'arquivo')).replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,180)||'arquivo'}
function responseMaterial(row){return {...row,extracted_text:undefined,file_path:undefined,has_file:Boolean(row.file_path)}}
function logFor(req,type,payload){logEvent(req.space.id,type,payload)}
function normalizeEmail(value){return String(value||'').trim().toLowerCase()}
function requireString(value,label,min=1,max=2000){if(typeof value!=='string'||value.trim().length<min||value.trim().length>max)throw fail(400,`${label} precisa ter entre ${min} e ${max} caracteres.`);return value.trim()}
function selectedIds(value){if(!Array.isArray(value))return [];return [...new Set(value.map(Number).filter(Number.isInteger))].slice(0,40)}
function visibleSources(hits){return citationList(hits)}
function ensureSubject(spaceId,id){const s=db.prepare('SELECT * FROM subjects WHERE id=? AND space_id=?').get(Number(id),spaceId);if(!s)throw fail(404,'Assunto não encontrado neste espaço.');return s}
function sourceHits(spaceId,materialIds,query){const ids=selectedIds(materialIds);if(ids.length){for(const id of ids)if(!rowInSpace('materials',id,spaceId))throw fail(404,'Uma das fontes selecionadas não pertence a este espaço.')}return sourcesForQuery(spaceId,ids,query)}
function parseQuestionConfig(body){const qty=Math.max(1,Math.min(30,Number(body.quantity)||8));const difficulty=['easy','medium','hard','mixed'].includes(body.difficulty)?body.difficulty:'mixed';const type=['multiple_choice','true_false','short_answer','cloze','case'].includes(body.type)?body.type:'multiple_choice';return {qty,difficulty,type}}

app.get('/api/health',(req,res)=>res.json({ok:true,service:'study-space',time:new Date().toISOString()}));
app.post('/api/auth/signup',authLimiter,asyncRoute(async(req,res)=>{
 const name=requireString(req.body.name,'Nome',2,80),email=normalizeEmail(req.body.email),password=String(req.body.password||'');
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw fail(400,'Informe um e-mail válido.');if(password.length<10||password.length>200)throw fail(400,'A senha precisa ter entre 10 e 200 caracteres.');
 if(db.prepare('SELECT id FROM users WHERE email=?').get(email))throw fail(409,'Já existe uma conta com esse e-mail.');
 let userId,spaceId;transaction(()=>{userId=db.prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)').run(name,email,passwordHash(password)).lastInsertRowid;spaceId=db.prepare('INSERT INTO spaces(user_id,name) VALUES(?,?)').run(userId,'Meu espaço de estudos').lastInsertRowid;db.prepare('INSERT INTO notebooks(space_id,name) VALUES(?,?)').run(spaceId,'Geral');db.prepare('INSERT INTO preferences(space_id) VALUES(?)').run(spaceId);logEvent(spaceId,'ContaCriada',{userId})});
 const user=db.prepare('SELECT id,name,email FROM users WHERE id=?').get(userId);res.cookie('study_session',createToken(user),cookieOptions(req)).status(201).json({user,spaceId});
}));
app.post('/api/auth/login',authLimiter,asyncRoute(async(req,res)=>{const email=normalizeEmail(req.body.email),password=String(req.body.password||'');const record=db.prepare('SELECT * FROM users WHERE email=?').get(email);if(!record||!verifyPassword(password,record.password_hash))throw fail(401,'E-mail ou senha incorretos.');res.cookie('study_session',createToken(record),cookieOptions(req)).json({user:safeUser(record)})}));
app.post('/api/auth/logout',(req,res)=>{res.clearCookie('study_session',{httpOnly:true,sameSite:'lax',secure:Boolean(req.secure),path:'/'}).json({ok:true})});
app.get('/api/auth/me',requireAuth,asyncRoute(async(req,res)=>{res.json({user:safeUser(req.user),spaces:db.prepare('SELECT id,name,created_at FROM spaces WHERE user_id=? ORDER BY id').all(req.user.id)})}));
app.post('/api/auth/recovery',authLimiter,asyncRoute(async(req,res)=>{
 const email=normalizeEmail(req.body.email);if(!process.env.SMTP_HOST)throw fail(503,'Recuperação por e-mail precisa de SMTP_HOST, SMTP_USER, SMTP_PASS e MAIL_FROM no .env.');
 const user=db.prepare('SELECT * FROM users WHERE email=?').get(email);if(user){const token=randomToken(),hash=tokenHash(token),expires=new Date(Date.now()+30*60*1000).toISOString();db.prepare('UPDATE password_resets SET used_at=CURRENT_TIMESTAMP WHERE user_id=? AND used_at IS NULL').run(user.id);db.prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,?)').run(user.id,hash,expires);const link=`${req.protocol}://${req.get('host')}/reset-password?token=${encodeURIComponent(token)}`;const transport=nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT)||587,secure:process.env.SMTP_SECURE==='true',auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}});await transport.sendMail({from:process.env.MAIL_FROM,to:user.email,subject:'Redefina sua senha do Study Space',text:`Olá, ${user.name}. Use este link, válido por 30 minutos, para definir uma nova senha: ${link}`})}res.json({message:'Se a conta existir, enviaremos instruções para o e-mail cadastrado.'});
}));
app.post('/api/auth/reset-password',authLimiter,asyncRoute(async(req,res)=>{const token=String(req.body.token||''),password=String(req.body.password||'');if(password.length<10||password.length>200)throw fail(400,'A senha precisa ter entre 10 e 200 caracteres.');const record=db.prepare('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL').get(tokenHash(token));if(!record||new Date(record.expires_at)<new Date())throw fail(400,'Link inválido ou expirado. Solicite uma nova redefinição.');transaction(()=>{db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(passwordHash(password),record.user_id);db.prepare('UPDATE password_resets SET used_at=CURRENT_TIMESTAMP WHERE id=?').run(record.id)});res.json({ok:true})}));

app.use('/api',requireAuth);
app.get('/api/spaces',asyncRoute(async(req,res)=>res.json(db.prepare('SELECT id,name,created_at FROM spaces WHERE user_id=? ORDER BY id').all(req.user.id))));
app.post('/api/spaces',asyncRoute(async(req,res)=>{const name=requireString(req.body.name,'Nome do espaço',2,100);const id=transaction(()=>{const id=db.prepare('INSERT INTO spaces(user_id,name) VALUES(?,?)').run(req.user.id,name).lastInsertRowid;db.prepare('INSERT INTO notebooks(space_id,name) VALUES(?,?)').run(id,'Geral');db.prepare('INSERT INTO preferences(space_id) VALUES(?)').run(id);return id});res.status(201).json(db.prepare('SELECT * FROM spaces WHERE id=?').get(id))}));
app.patch('/api/spaces/:id',asyncRoute(async(req,res)=>{const row=db.prepare('SELECT * FROM spaces WHERE id=? AND user_id=?').get(Number(req.params.id),req.user.id);if(!row)throw fail(404,'Espaço não encontrado.');db.prepare('UPDATE spaces SET name=? WHERE id=?').run(requireString(req.body.name,'Nome',2,100),row.id);res.json(db.prepare('SELECT id,name,created_at FROM spaces WHERE id=?').get(row.id))}));
app.use('/api',requireSpace);

app.get('/api/bootstrap',asyncRoute(async(req,res)=>{const space=req.space;const prefs=db.prepare('SELECT * FROM preferences WHERE space_id=?').get(space.id);const notebooks=db.prepare('SELECT * FROM notebooks WHERE space_id=? ORDER BY id').all(space.id);const subjects=db.prepare('SELECT * FROM subjects WHERE space_id=? AND status!=? ORDER BY priority,name').all(space.id,'archived');const materials=db.prepare('SELECT m.id,m.name,m.original_name,m.mime_type,m.file_size,m.source_url,m.version,m.process_status,m.process_error,m.subject_id,m.notebook_id,m.created_at,s.name subject_name,(m.file_path!=\'\') has_file FROM materials m LEFT JOIN subjects s ON s.id=m.subject_id WHERE m.space_id=? ORDER BY m.created_at DESC').all(space.id);const dashboard=dashboardData(space.id);res.json({user:safeUser(req.user),space,spaces:db.prepare('SELECT id,name FROM spaces WHERE user_id=?').all(req.user.id),prefs,notebooks,subjects,materials,dashboard,aiAvailable:Boolean(process.env.OPENAI_API_KEY)});}));

app.get('/api/notebooks',asyncRoute(async(req,res)=>res.json(db.prepare('SELECT * FROM notebooks WHERE space_id=? ORDER BY name').all(req.space.id))));
app.post('/api/notebooks',asyncRoute(async(req,res)=>{const name=requireString(req.body.name,'Nome do caderno',1,100);const id=db.prepare('INSERT INTO notebooks(space_id,name,color) VALUES(?,?,?)').run(req.space.id,name,/^#[0-9a-f]{6}$/i.test(req.body.color)?req.body.color:'#6f9777').lastInsertRowid;logFor(req,'CadernoCriado',{notebookId:id});res.status(201).json(db.prepare('SELECT * FROM notebooks WHERE id=?').get(id))}));
app.patch('/api/notebooks/:id',asyncRoute(async(req,res)=>{const row=rowInSpace('notebooks',req.params.id,req.space.id);if(!row)throw fail(404,'Caderno não encontrado.');db.prepare('UPDATE notebooks SET name=? WHERE id=?').run(requireString(req.body.name,'Nome',1,100),row.id);res.json(db.prepare('SELECT * FROM notebooks WHERE id=?').get(row.id))}));
app.delete('/api/notebooks/:id',asyncRoute(async(req,res)=>{const row=rowInSpace('notebooks',req.params.id,req.space.id);if(!row)throw fail(404,'Caderno não encontrado.');db.prepare('DELETE FROM notebooks WHERE id=?').run(row.id);res.json({ok:true})}));

app.get('/api/subjects',asyncRoute(async(req,res)=>res.json(db.prepare('SELECT * FROM subjects WHERE space_id=? AND status!=? ORDER BY priority,name').all(req.space.id,'archived'))));
app.post('/api/subjects',asyncRoute(async(req,res)=>{const name=requireString(req.body.name,'Nome do assunto',2,120);const priority=Math.max(1,Math.min(5,Number(req.body.priority)||3));const minutes=Math.max(10,Math.min(240,Number(req.body.estimatedMinutes)||45));let notebookId=req.body.notebookId?Number(req.body.notebookId):null;if(notebookId&&!rowInSpace('notebooks',notebookId,req.space.id))throw fail(404,'Caderno não encontrado.');let result;try{result=db.prepare('INSERT INTO subjects(space_id,notebook_id,name,priority,estimated_minutes,exam_date) VALUES(?,?,?,?,?,?)').run(req.space.id,notebookId,name,priority,minutes,req.body.examDate||null)}catch(error){if(String(error.message).includes('UNIQUE'))throw fail(409,'Este assunto já existe neste espaço.');throw error}logFor(req,'AssuntoCriado',{subjectId:result.lastInsertRowid});res.status(201).json(db.prepare('SELECT * FROM subjects WHERE id=?').get(result.lastInsertRowid))}));
app.patch('/api/subjects/:id',asyncRoute(async(req,res)=>{const row=ensureSubject(req.space.id,req.params.id);const name=req.body.name===undefined?row.name:requireString(req.body.name,'Nome',2,120);const priority=req.body.priority===undefined?row.priority:Math.max(1,Math.min(5,Number(req.body.priority)||3));const minutes=req.body.estimatedMinutes===undefined?row.estimated_minutes:Math.max(10,Math.min(240,Number(req.body.estimatedMinutes)||45));const status=['new','learning','mastered','archived'].includes(req.body.status)?req.body.status:row.status;let notebook=req.body.notebookId===undefined?row.notebook_id:(Number(req.body.notebookId)||null);if(notebook&&!rowInSpace('notebooks',notebook,req.space.id))throw fail(404,'Caderno não encontrado.');db.prepare('UPDATE subjects SET name=?,priority=?,estimated_minutes=?,status=?,notebook_id=?,exam_date=? WHERE id=?').run(name,priority,minutes,status,notebook,req.body.examDate===undefined?row.exam_date:req.body.examDate||null,row.id);res.json(db.prepare('SELECT * FROM subjects WHERE id=?').get(row.id))}));
app.delete('/api/subjects/:id',asyncRoute(async(req,res)=>{const row=ensureSubject(req.space.id,req.params.id);db.prepare("UPDATE subjects SET status='archived' WHERE id=?").run(row.id);logFor(req,'AssuntoArquivado',{subjectId:row.id});res.json({ok:true})}));

app.get('/api/materials',asyncRoute(async(req,res)=>res.json(db.prepare('SELECT m.id,m.name,m.original_name,m.mime_type,m.file_size,m.source_url,m.version,m.process_status,m.process_error,m.subject_id,m.notebook_id,m.created_at,s.name subject_name,(m.file_path!=\'\') has_file FROM materials m LEFT JOIN subjects s ON s.id=m.subject_id WHERE m.space_id=? ORDER BY m.created_at DESC').all(req.space.id))));
app.post('/api/materials',upload.single('file'),asyncRoute(async(req,res)=>{if(!req.file)throw fail(400,'Selecione um arquivo.');const ext=path.extname(req.file.originalname).slice(1).toLowerCase();const subjectId=Number(req.body.subjectId)||null;const notebookId=Number(req.body.notebookId)||null;if(subjectId)ensureSubject(req.space.id,subjectId);if(notebookId&&!rowInSpace('notebooks',notebookId,req.space.id))throw fail(404,'Caderno não encontrado.');const name=requireString(req.body.name||path.basename(req.file.originalname,path.extname(req.file.originalname)),'Nome do material',1,180);const relative=path.relative(root,req.file.path);let materialId;transaction(()=>{materialId=db.prepare(`INSERT INTO materials(space_id,subject_id,notebook_id,name,original_name,mime_type,file_path,file_size,process_status) VALUES(?,?,?,?,?,?,?,?,?)`).run(req.space.id,subjectId,notebookId,name,toSafeFilename(req.file.originalname),req.file.mimetype,relative,req.file.size,'queued').lastInsertRowid;db.prepare('INSERT INTO material_versions(material_id,version,original_name,file_path,mime_type,file_size,process_status) VALUES(?,?,?,?,?,?,?)').run(materialId,1,toSafeFilename(req.file.originalname),relative,req.file.mimetype,req.file.size,'queued');const jobId=db.prepare('INSERT INTO processing_jobs(space_id,material_id,job_type) VALUES(?,?,?)').run(req.space.id,materialId,'extract').lastInsertRowid;logFor(req,'MaterialImportado',{materialId});enqueueProcessing(jobId)});res.status(202).json(responseMaterial(db.prepare('SELECT * FROM materials WHERE id=?').get(materialId)))}));
app.post('/api/materials/reference',asyncRoute(async(req,res)=>{const name=requireString(req.body.name,'Nome da fonte',2,180),url=requireString(req.body.url,'URL',8,2000);let parsed;try{parsed=new URL(url)}catch{throw fail(400,'Informe uma URL válida.')}if(!['https:','http:'].includes(parsed.protocol))throw fail(400,'A fonte precisa usar HTTP ou HTTPS.');const subjectId=Number(req.body.subjectId)||null;if(subjectId)ensureSubject(req.space.id,subjectId);const id=db.prepare(`INSERT INTO materials(space_id,subject_id,name,original_name,mime_type,file_path,file_size,source_url,process_status) VALUES(?,?,?,?,?,?,?,?,?)`).run(req.space.id,subjectId,name,name,'text/uri-list','',0,parsed.href,'reference').lastInsertRowid;logFor(req,'FonteExternaAdicionada',{materialId:id,url:parsed.origin});res.status(201).json(responseMaterial(db.prepare('SELECT * FROM materials WHERE id=?').get(id)))}));
app.post('/api/materials/import-url',asyncRoute(async(req,res)=>{const url=requireString(req.body.url,'URL',8,2000);let source;try{source=await fetchReference(url)}catch(error){throw fail(422,error.message)}const subjectId=Number(req.body.subjectId)||null;if(subjectId)ensureSubject(req.space.id,subjectId);const suppliedName=typeof req.body.name==='string'&&req.body.name.trim()?requireString(req.body.name,'Nome',2,180):path.basename(source.name,path.extname(source.name)).slice(0,180);const original=toSafeFilename(`${suppliedName}${path.extname(source.name)||'.txt'}`);const diskName=`${crypto.randomUUID()}${path.extname(original)}`;const absolute=path.join(uploadDir,diskName);await fsp.writeFile(absolute,source.body,{flag:'wx'});const relative=path.relative(root,absolute);let materialId;try{transaction(()=>{materialId=db.prepare('INSERT INTO materials(space_id,subject_id,name,original_name,mime_type,file_path,file_size,source_url,process_status) VALUES(?,?,?,?,?,?,?,?,?)').run(req.space.id,subjectId,suppliedName,original,source.mime,relative,source.body.length,new URL(url).href,'queued').lastInsertRowid;db.prepare('INSERT INTO material_versions(material_id,version,original_name,file_path,mime_type,file_size,process_status) VALUES(?,?,?,?,?,?,?)').run(materialId,1,original,relative,source.mime,source.body.length,'queued');const job=db.prepare('INSERT INTO processing_jobs(space_id,material_id,job_type) VALUES(?,?,?)').run(req.space.id,materialId,'extract').lastInsertRowid;logFor(req,'MaterialImportado',{materialId,source:'url'});enqueueProcessing(job)})}catch(error){await fsp.rm(absolute,{force:true});throw error}res.status(202).json(responseMaterial(db.prepare('SELECT * FROM materials WHERE id=?').get(materialId)))}));
app.patch('/api/materials/:id',asyncRoute(async(req,res)=>{const m=rowInSpace('materials',req.params.id,req.space.id);if(!m)throw fail(404,'Material não encontrado.');const name=req.body.name===undefined?m.name:requireString(req.body.name,'Nome',1,180);const subjectId=req.body.subjectId===undefined?m.subject_id:(Number(req.body.subjectId)||null);if(subjectId)ensureSubject(req.space.id,subjectId);const notebookId=req.body.notebookId===undefined?m.notebook_id:(Number(req.body.notebookId)||null);if(notebookId&&!rowInSpace('notebooks',notebookId,req.space.id))throw fail(404,'Caderno não encontrado.');db.prepare('UPDATE materials SET name=?,subject_id=?,notebook_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(name,subjectId,notebookId,m.id);res.json(responseMaterial(db.prepare('SELECT * FROM materials WHERE id=?').get(m.id)))}));
app.get('/api/materials/:id/versions',asyncRoute(async(req,res)=>{const m=rowInSpace('materials',req.params.id,req.space.id);if(!m)throw fail(404,'Material não encontrado.');res.json(db.prepare('SELECT id,version,original_name,mime_type,file_size,process_status,process_error,created_at FROM material_versions WHERE material_id=? ORDER BY version DESC').all(m.id))}));
app.post('/api/materials/:id/versions',upload.single('file'),asyncRoute(async(req,res)=>{const m=rowInSpace('materials',req.params.id,req.space.id);if(!m)throw fail(404,'Material não encontrado.');if(!req.file)throw fail(400,'Selecione uma nova versão.');const version=m.version+1,relative=path.relative(root,req.file.path),original=toSafeFilename(req.file.originalname);let jobId;transaction(()=>{db.prepare('UPDATE material_versions SET original_name=?,file_path=?,mime_type=?,file_size=?,process_status=?,process_error=NULL,extracted_text=(SELECT extracted_text FROM materials WHERE id=?) WHERE material_id=? AND version=?').run(m.original_name,m.file_path,m.mime_type,m.file_size,m.process_status,m.id,m.id,m.version);db.prepare("UPDATE materials SET original_name=?,file_path=?,mime_type=?,file_size=?,version=?,process_status='queued',process_error=NULL,extracted_text='',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(original,relative,req.file.mimetype,req.file.size,version,m.id);db.prepare('INSERT INTO material_versions(material_id,version,original_name,file_path,mime_type,file_size,process_status) VALUES(?,?,?,?,?,?,?)').run(m.id,version,original,relative,req.file.mimetype,req.file.size,'queued');jobId=db.prepare('INSERT INTO processing_jobs(space_id,material_id,job_type) VALUES(?,?,?)').run(req.space.id,m.id,'extract').lastInsertRowid;logFor(req,'NovaVersaoDeMaterial',{materialId:m.id,version});enqueueProcessing(jobId)});res.status(202).json(responseMaterial(db.prepare('SELECT * FROM materials WHERE id=?').get(m.id)))}));
app.delete('/api/materials/:id',asyncRoute(async(req,res)=>{const m=rowInSpace('materials',req.params.id,req.space.id);if(!m)throw fail(404,'Material não encontrado.');const files=db.prepare('SELECT file_path FROM material_versions WHERE material_id=?').all(m.id).map(r=>r.file_path);if(m.file_path)files.push(m.file_path);transaction(()=>{db.prepare('DELETE FROM materials WHERE id=?').run(m.id);logFor(req,'MaterialExcluido',{materialId:m.id})});for(const rel of new Set(files.filter(Boolean)))await fsp.rm(path.resolve(root,rel),{force:true});res.json({ok:true})}));
