app.get('/api/search',asyncRoute(async(req,res)=>{const q=requireString(String(req.query.q||''),'Busca',2,200);const ids=(String(req.query.materialIds||'').split(',').filter(Boolean)).map(Number);if(ids.length)for(const id of ids)if(!rowInSpace('materials',id,req.space.id))throw fail(404,'Fonte inválida.');const hits=retrieveSources(req.space.id,ids,q,15);res.json({query:q,results:hits.map(h=>({id:h.chunk_id,materialId:h.material_id,materialName:h.material_name,page:h.page_number,content:h.content,score:h.score}))})}));

