app.post('/api/studio/generate',aiLimiter,asyncRoute(async(req,res)=>{const type=['summary','guide','workbook','comparison','concept_map','notes','flashcards','key_concepts','review_guide','deep_dive'].includes(req.body.type)?req.body.type:'summary';const depth=['concise','balanced','detailed'].includes(req.body.depth)?req.body.depth:'balanced';const goal=requireString(req.body.goal||'Ajudar a compreender e revisar o assunto.','Objetivo',4,400);const title=requireString(req.body.title||({summary:'Resumo',guide:'Guia de estudo',workbook:'Apostila',comparison:'Tabela comparativa',concept_map:'Mapa conceitual',notes:'Fichamento',flashcards:'Flashcards',key_concepts:'Conceitos fundamentais',review_guide:'Roteiro de revisão',deep_dive:'Aprofundamento'}[type]),'Título',2,180);const subjectId=Number(req.body.subjectId)||null;if(subjectId)ensureSubject(req.space.id,subjectId);const materials=selectedIds(req.body.materialIds);if(!materials.length)throw fail(400,'Selecione ao menos uma fonte.');const query=`${title} ${goal} ${subjectId?ensureSubject(req.space.id,subjectId).name:''}`;const hits=sourceHits(req.space.id,materials,query);const prompt=`Você é um tutor de estudos cuidadoso. Escreva em português brasileiro. Use apenas as fontes abaixo para afirmações factuais. Cite cada afirmação importante com os marcadores [S1], [S2] etc. Se a fonte não sustentar algo, diga que não há evidência no material. Diferencie eventuais divergências. Não invente páginas.\n\nTipo: ${type}\nProfundidade: ${depth}\nObjetivo: ${goal}\nTítulo: ${title}\n\nFONTES:\n${contextBlock(hits)}`;const body=await generate(prompt,{maxOutputTokens:Math.min(6000,depth==='detailed'?5000:3000)});const id=transaction(()=>{const id=db.prepare('INSERT INTO generated_materials(space_id,subject_id,title,kind,body,generation_config) VALUES(?,?,?,?,?,?)').run(req.space.id,subjectId,title,type,body,JSON.stringify({depth,goal,materialIds:materials,model:process.env.OPENAI_MODEL||'gpt-4.1-mini'})).lastInsertRowid;db.prepare('INSERT INTO generated_material_versions(generated_material_id,version,body,created_at) VALUES(?,?,?,CURRENT_TIMESTAMP)').run(id,1,body);hits.forEach(h=>db.prepare('INSERT INTO generated_sources(generated_material_id,chunk_id,citation_label,material_name,page_number,excerpt) VALUES(?,?,?,?,?,?)').run(id,h.chunk_id,h.citation,h.material_name,h.page_number,h.content));logFor(req,'MaterialGerado',{generatedMaterialId:id,type,sourceIds:materials});return id});res.status(201).json({material:db.prepare('SELECT * FROM generated_materials WHERE id=?').get(id),sources:visibleSources(hits)})}));
app.get('/api/studio/materials/:id',asyncRoute(async(req,res)=>{const row=rowInSpace('generated_materials',req.params.id,req.space.id);if(!row)throw fail(404,'Material gerado não encontrado.');const sources=db.prepare('SELECT gs.citation_label citation,gs.chunk_id chunk_id,COALESCE(m.id,0) material_id,COALESCE(m.name,gs.material_name) material_name,COALESCE(c.page_number,gs.page_number) page_number,COALESCE(c.content,gs.excerpt) content FROM generated_sources gs LEFT JOIN material_chunks c ON c.id=gs.chunk_id LEFT JOIN materials m ON m.id=c.material_id WHERE gs.generated_material_id=?').all(row.id);const versions=db.prepare('SELECT version,created_at FROM generated_material_versions WHERE generated_material_id=? ORDER BY version DESC').all(row.id);res.json({material:row,sources:sourceRowsToRefs(sources),versions})}));
function sourceRowsToRefs(rows){return rows.map(r=>({citation:r.citation,chunkId:r.chunk_id,materialId:r.material_id,materialName:r.material_name,page:r.page_number,excerpt:r.content}))}
app.patch('/api/studio/materials/:id',asyncRoute(async(req,res)=>{const row=rowInSpace('generated_materials',req.params.id,req.space.id);if(!row)throw fail(404,'Material gerado não encontrado.');const title=req.body.title===undefined?row.title:requireString(req.body.title,'Título',2,180);const body=req.body.body===undefined?row.body:requireString(req.body.body,'Conteúdo',1,30000);const version=row.version+1;transaction(()=>{db.prepare('UPDATE generated_materials SET title=?,body=?,version=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(title,body,version,row.id);db.prepare('INSERT INTO generated_material_versions(generated_material_id,version,body,created_at) VALUES(?,?,?,CURRENT_TIMESTAMP)').run(row.id,version,body)});res.json(db.prepare('SELECT * FROM generated_materials WHERE id=?').get(row.id))}));
