app.get('/api/questions',asyncRoute(async(req,res)=>{const subjectId=Number(req.query.subjectId)||null;const rows=db.prepare(`SELECT q.id,q.subject_id,q.prompt,q.question_type,q.difficulty,q.created_at,s.name subject_name,(SELECT COUNT(*) FROM attempts a WHERE a.question_id=q.id) attempts,(SELECT COUNT(*) FROM attempts a WHERE a.question_id=q.id AND a.is_correct=1) correct FROM questions q LEFT JOIN subjects s ON s.id=q.subject_id WHERE q.space_id=? ${subjectId?'AND q.subject_id=?':''} ORDER BY q.created_at DESC LIMIT 200`).all(...(subjectId?[req.space.id,subjectId]:[req.space.id]));res.json(rows)}));
app.post('/api/questions/generate',aiLimiter,asyncRoute(async(req,res)=>{const subject=ensureSubject(req.space.id,req.body.subjectId);const materials=selectedIds(req.body.materialIds);if(!materials.length)throw fail(400,'Selecione uma ou mais fontes para fundamentar as questões.');const {qty,difficulty,type}=parseQuestionConfig(req.body);const goal=requireString(req.body.goal||'Verificar compreensão e retenção.','Objetivo',3,300);const hits=sourceHits(req.space.id,materials,`${subject.name} ${goal}`);const prompt=`Crie exatamente ${qty} questões em português brasileiro baseadas exclusivamente nas fontes. Tipo pedido: ${type}. Dificuldade: ${difficulty}. Objetivo: ${goal}. Retorne APENAS JSON válido no formato {"questions":[{"prompt":"...","type":"${type}","options":["..."],"correct_index":0,"answer":"...","explanation":"...","difficulty":"easy|medium|hard","source_citations":["S1"]}]}. Em múltipla escolha, crie 4 alternativas e apenas uma correta. Em verdadeiro/falso, options deve ter ["Verdadeiro","Falso"]. Em resposta curta/caso/lacuna, options=[] e answer deve conter um critério de correção claro. A explicação deve justificar a resposta e incluir [S#]. Não invente citações.\n\nFONTES:\n${contextBlock(hits)}`;const result=parseJsonOutput(await generate(prompt,{maxOutputTokens:Math.min(7000,qty*350)}));const qs=Array.isArray(result)?result:result.questions;if(!Array.isArray(qs)||qs.length<1)throw fail(502,'A IA não retornou questões válidas.');const ids=[];transaction(()=>{for(const q of qs.slice(0,qty)){if(typeof q.prompt!=='string'||!q.prompt.trim())continue;const questionType=['multiple_choice','true_false','short_answer','cloze','case'].includes(q.type)?q.type:type;const options=Array.isArray(q.options)?q.options.slice(0,6):[];const answer={correct_index:Number.isInteger(q.correct_index)?q.correct_index:null,answer:String(q.answer||''),source_citations:Array.isArray(q.source_citations)?q.source_citations:[]};const id=db.prepare('INSERT INTO questions(space_id,subject_id,prompt,question_type,options_json,answer_json,explanation,difficulty) VALUES(?,?,?,?,?,?,?,?)').run(req.space.id,subject.id,q.prompt.trim(),questionType,JSON.stringify(options),JSON.stringify(answer),String(q.explanation||''),['easy','medium','hard'].includes(q.difficulty)?q.difficulty:difficulty==='mixed'?'medium':difficulty).lastInsertRowid;hits.forEach(h=>{if(answer.source_citations.includes(h.citation))db.prepare('INSERT OR IGNORE INTO question_sources(question_id,chunk_id,citation_label) VALUES(?,?,?)').run(id,h.chunk_id,h.citation)});ids.push(id)}if(!ids.length)throw fail(502,'A IA não retornou nenhuma questão utilizável.');logFor(req,'BancoDeQuestoesGerado',{subjectId:subject.id,questionIds:ids})});res.status(201).json({questions:ids.map(id=>questionPublic(db.prepare('SELECT * FROM questions WHERE id=?').get(id))),sources:visibleSources(hits)})}));
function questionPublic(q){return {id:q.id,subjectId:q.subject_id,prompt:q.prompt,type:q.question_type,options:JSON.parse(q.options_json||'[]'),difficulty:q.difficulty,createdAt:q.created_at}}

app.post('/api/study/sessions',aiLimiter,asyncRoute(async(req,res)=>{const subject=ensureSubject(req.space.id,req.body.subjectId);const {qty,difficulty,type}=parseQuestionConfig(req.body);const materials=selectedIds(req.body.materialIds);if(!materials.length)throw fail(400,'Escolha os materiais que devem fundamentar esta sessão.');for(const id of materials)if(!rowInSpace('materials',id,req.space.id))throw fail(404,'Fonte inválida.');const reviewId=Number(req.body.reviewId)||null;let review=null;if(reviewId){review=db.prepare("SELECT * FROM reviews WHERE id=? AND space_id=? AND status IN ('scheduled','overdue')").get(reviewId,req.space.id);if(!review||review.subject_id!==subject.id)throw fail(404,'Revisão não encontrada para este assunto.')}const hits=sourceHits(req.space.id,materials,`${subject.name} recuperação ativa questões conceitos principais`);const prompt=`Gere ${qty} questões em português brasileiro para uma sessão de estudo ativo. Use somente as fontes abaixo. Tipo: ${type}; dificuldade: ${difficulty}. Devolva JSON estrito {"questions":[{"prompt":"...","type":"...","options":["..."],"correct_index":0,"answer":"...","explanation":"...","difficulty":"easy|medium|hard","source_citations":["S1"]}]}. Questões objetivas com quatro alternativas (exceto verdadeiro/falso). Inclua explicação e fonte [S#]. Sem fatos externos.\n\nFONTES:\n${contextBlock(hits)}`;const result=parseJsonOutput(await generate(prompt,{maxOutputTokens:Math.min(7000,qty*350)}));const qs=(Array.isArray(result)?result:result.questions||[]).slice(0,qty);if(!qs.length)throw fail(502,'Não foi possível gerar uma sessão de questões.');const sessionId=transaction(()=>{const sessionId=db.prepare('INSERT INTO study_sessions(space_id,subject_id,review_id,session_type,started_at,questions_total) VALUES(?,?,?,?,?,?)').run(req.space.id,subject.id,reviewId,review?'review':'active',new Date().toISOString(),qs.length).lastInsertRowid;for(const q of qs){const typeName=['multiple_choice','true_false','short_answer','cloze','case'].includes(q.type)?q.type:type;const ans={correct_index:Number.isInteger(q.correct_index)?q.correct_index:null,answer:String(q.answer||''),source_citations:Array.isArray(q.source_citations)?q.source_citations:[]};const qid=db.prepare('INSERT INTO questions(space_id,subject_id,prompt,question_type,options_json,answer_json,explanation,difficulty) VALUES(?,?,?,?,?,?,?,?)').run(req.space.id,subject.id,String(q.prompt),typeName,JSON.stringify(Array.isArray(q.options)?q.options.slice(0,6):[]),JSON.stringify(ans),String(q.explanation||''),q.difficulty||difficulty).lastInsertRowid;for(const h of hits)if(ans.source_citations.includes(h.citation))db.prepare('INSERT OR IGNORE INTO question_sources(question_id,chunk_id,citation_label) VALUES(?,?,?)').run(qid,h.chunk_id,h.citation);db.prepare('INSERT INTO session_questions(session_id,question_id,sort_order) VALUES(?,?,?)').run(sessionId,qid,db.prepare('SELECT COUNT(*) n FROM session_questions WHERE session_id=?').get(sessionId).n)}logFor(req,'SessaoIniciada',{sessionId,subjectId:subject.id,reviewId});return sessionId});res.status(201).json({sessionId,subject,reviewId,questions:db.prepare('SELECT q.id,q.prompt,q.question_type,q.options_json,q.difficulty,sq.sort_order FROM session_questions sq JOIN questions q ON q.id=sq.question_id WHERE sq.session_id=? ORDER BY sq.sort_order').all(sessionId).map(q=>({...q,options:JSON.parse(q.options_json)})),sources:visibleSources(hits)})}));
app.get('/api/study/sessions/:id',asyncRoute(async(req,res)=>{const session=db.prepare('SELECT ss.*,s.name subject_name FROM study_sessions ss LEFT JOIN subjects s ON s.id=ss.subject_id WHERE ss.id=? AND ss.space_id=?').get(Number(req.params.id),req.space.id);if(!session)throw fail(404,'Sessão não encontrada.');const questions=db.prepare('SELECT q.id,q.prompt,q.question_type,q.options_json,q.difficulty,sq.sort_order,a.is_correct,a.score,a.feedback,a.answer_json FROM session_questions sq JOIN questions q ON q.id=sq.question_id LEFT JOIN attempts a ON a.session_id=sq.session_id AND a.question_id=q.id WHERE sq.session_id=? ORDER BY sq.sort_order').all(session.id);res.json({session,questions:questions.map(q=>({...q,options:JSON.parse(q.options_json),result:q.is_correct===null?null:{correct:Boolean(q.is_correct),score:q.score,feedback:q.feedback,answer:JSON.parse(q.answer_json||'null')}}))})}));
app.post('/api/study/attempts',aiLimiter,asyncRoute(async(req,res)=>{const session=db.prepare('SELECT * FROM study_sessions WHERE id=? AND space_id=?').get(Number(req.body.sessionId),req.space.id);if(!session||session.completed_at)throw fail(404,'Sessão ativa não encontrada.');const question=db.prepare('SELECT q.* FROM session_questions sq JOIN questions q ON q.id=sq.question_id WHERE sq.session_id=? AND q.id=?').get(session.id,Number(req.body.questionId));if(!question)throw fail(404,'Questão não pertence a esta sessão.');if(db.prepare('SELECT id FROM attempts WHERE session_id=? AND question_id=?').get(session.id,question.id))throw fail(409,'Esta questão já foi respondida nesta sessão.');const answer=req.body.answer;const expected=JSON.parse(question.answer_json);let correct=false,score=0,feedback='',modelAnswer=expected.answer;const elapsed=Math.max(0,Math.min(3600,Number(req.body.durationSeconds)||0));
 if(['multiple_choice','true_false'].includes(question.question_type)){const value=Number(answer);correct=Number.isInteger(value)&&value===expected.correct_index;score=correct?1:0;feedback=question.explanation||`Resposta correta: ${expected.answer}`;}
 else {const refs=db.prepare('SELECT qs.citation_label,c.content,m.name material_name FROM question_sources qs JOIN material_chunks c ON c.id=qs.chunk_id JOIN materials m ON m.id=c.material_id WHERE qs.question_id=?').all(question.id);const grading=await generate(`Avalie a resposta do estudante em português com base no gabarito e fontes fornecidas. Retorne APENAS JSON {"score":numero_de_0_a_1,"feedback":"...","model_answer":"..."}. Dê crédito parcial justo, explique o que está correto e o que falta, não introduza fatos não apoiados.\nQUESTÃO: ${question.prompt}\nCRITÉRIO/GABARITO: ${expected.answer}\nRESPOSTA DO ESTUDANTE: ${String(answer||'').slice(0,5000)}\nEXPLICAÇÃO: ${question.explanation}\nFONTES: ${refs.map(r=>`[${r.citation_label}] ${r.material_name}: ${r.content}`).join('\n')}` ,{maxOutputTokens:700});const parsed=parseJsonOutput(grading);score=Math.max(0,Math.min(1,Number(parsed.score)||0));correct=score>=.7;feedback=String(parsed.feedback||'');modelAnswer=String(parsed.model_answer||expected.answer)}
 const attemptId=db.prepare('INSERT INTO attempts(question_id,space_id,subject_id,session_id,answer_json,is_correct,score,feedback,duration_seconds) VALUES(?,?,?,?,?,?,?,?,?)').run(question.id,req.space.id,session.subject_id,session.id,JSON.stringify(answer??null),correct?1:0,score,feedback,elapsed).lastInsertRowid;
 const subject=ensureSubject(req.space.id,session.subject_id);const current=Number(subject.mastery)||0;const mastery=current===0?score:Math.max(0,Math.min(1,current*.72+score*.28));const status=mastery>=.85?'mastered':mastery>0?'learning':'new';db.prepare('UPDATE subjects SET mastery=?,status=? WHERE id=?').run(mastery,status,subject.id);db.prepare('UPDATE study_sessions SET questions_correct=questions_correct+?,duration_minutes=duration_minutes+? WHERE id=?').run(correct?1:0,Math.floor(elapsed/60),session.id);logFor(req,'QuestaoRespondida',{attemptId,questionId:question.id,subjectId:subject.id,correct,score,mastery});const refs=db.prepare('SELECT qs.citation_label citation,m.name material_name,c.page_number FROM question_sources qs JOIN material_chunks c ON c.id=qs.chunk_id JOIN materials m ON m.id=c.material_id WHERE qs.question_id=?').all(question.id);res.status(201).json({attemptId,correct,score,feedback,modelAnswer,explanation:question.explanation,sources:refs,mastery});}));
app.post('/api/study/sessions/:id/complete',asyncRoute(async(req,res)=>{const session=db.prepare('SELECT * FROM study_sessions WHERE id=? AND space_id=?').get(Number(req.params.id),req.space.id);if(!session)throw fail(404,'Sessão não encontrada.');if(session.completed_at)return res.json({session,alreadyCompleted:true});const total=db.prepare('SELECT COUNT(*) n FROM attempts WHERE session_id=?').get(session.id).n;if(total<session.questions_total)throw fail(409,'Responda todas as questões antes de concluir a sessão.');const now=new Date(),date=toISODate(now),duration=Math.max(1,Math.round((now-new Date(session.started_at))/60000));let cycleId=null;transaction(()=>{db.prepare('UPDATE study_sessions SET completed_at=?,duration_minutes=MAX(duration_minutes,?) WHERE id=?').run(now.toISOString(),duration,session.id);if(session.review_id){const review=db.prepare('SELECT * FROM reviews WHERE id=? AND space_id=?').get(session.review_id,req.space.id);if(review){cycleId=review.cycle_id;const score=db.prepare('SELECT AVG(score) score FROM attempts WHERE session_id=?').get(session.id).score||0;db.prepare("UPDATE reviews SET status='completed',completed_at=?,score=? WHERE id=?").run(now.toISOString(),score,review.id);logFor(req,'RevisaoConcluida',{reviewId:review.id,score});if(score<.6){const plan=planForSpace(req.space.id).id;db.prepare("INSERT INTO plan_items(plan_id,space_id,subject_id,scheduled_for,kind,title,estimated_minutes,sort_order) VALUES(?,?,?,?,?,?,?,999)").run(plan,req.space.id,review.subject_id,date,'reinforcement','Reforço · '+ensureSubject(req.space.id,review.subject_id).name,25)}}}else{cycleId=db.prepare("SELECT id FROM review_cycles WHERE space_id=? AND subject_id=? AND status='active' ORDER BY id DESC LIMIT 1").get(req.space.id,session.subject_id)?.id||null;if(!cycleId){cycleId=db.prepare('INSERT INTO review_cycles(space_id,subject_id,study_session_id,started_at) VALUES(?,?,?,?)').run(req.space.id,session.subject_id,session.id,date).lastInsertRowid;[7,14,21,30].forEach((days,index)=>db.prepare('INSERT INTO reviews(cycle_id,space_id,subject_id,stage,due_at) VALUES(?,?,?,?,?)').run(cycleId,req.space.id,session.subject_id,index+1,addDays(date,days)));logFor(req,'AssuntoConcluido',{subjectId:session.subject_id,cycleId,startedAt:date,intervals:[7,14,21,30]})}else{logFor(req,'EstudoConcluido',{subjectId:session.subject_id,sessionId:session.id})}}});const updated=db.prepare('SELECT * FROM study_sessions WHERE id=?').get(session.id);const reviewQueue=db.prepare('SELECT * FROM reviews WHERE cycle_id=? ORDER BY stage').all(cycleId||session.review_id);res.json({session:updated,cycleId,reviews:reviewQueue})}));

app.get('/api/reviews',asyncRoute(async(req,res)=>{const status=req.query.status;const rows=db.prepare(`SELECT r.*,s.name subject_name,rc.started_at FROM reviews r JOIN subjects s ON s.id=r.subject_id JOIN review_cycles rc ON rc.id=r.cycle_id WHERE r.space_id=? ${['scheduled','overdue','completed'].includes(status)?'AND r.status=?':''} ORDER BY r.due_at,r.stage`).all(...(status&&['scheduled','overdue','completed'].includes(status)?[req.space.id,status]:[req.space.id]));const today=toISODate();for(const r of rows)if(r.status==='scheduled'&&r.due_at<today){db.prepare("UPDATE reviews SET status='overdue' WHERE id=?").run(r.id);r.status='overdue'}res.json(rows)}));
app.post('/api/reviews/:id/session',asyncRoute(async(req,res,next)=>{const review=db.prepare("SELECT r.*,s.name subject_name FROM reviews r JOIN subjects s ON s.id=r.subject_id WHERE r.id=? AND r.space_id=? AND r.status IN ('scheduled','overdue')").get(Number(req.params.id),req.space.id);if(!review)throw fail(404,'Revisão pendente não encontrada.');req.body.subjectId=review.subject_id;req.body.reviewId=review.id;req.body.materialIds=selectedIds(req.body.materialIds);if(!req.body.materialIds.length)req.body.materialIds=db.prepare("SELECT id FROM materials WHERE space_id=? AND subject_id=? AND process_status='ready'").all(req.space.id,review.subject_id).map(r=>r.id);if(!req.body.materialIds.length)throw fail(422,'Este assunto não tem material processado para gerar uma revisão.');req.body.quantity=req.body.quantity||5;req.body.difficulty=req.body.difficulty||'mixed';req.body.type=req.body.type||'multiple_choice';req.url='/api/study/sessions';next()}));
app.post('/api/reviews/:id/skip',asyncRoute(async(req,res)=>{const row=db.prepare("SELECT * FROM reviews WHERE id=? AND space_id=? AND status IN ('scheduled','overdue')").get(Number(req.params.id),req.space.id);if(!row)throw fail(404,'Revisão pendente não encontrada.');const date=req.body.dueAt||addDays(toISODate(),1);db.prepare("UPDATE reviews SET due_at=?,status='scheduled' WHERE id=?").run(date,row.id);logFor(req,'RevisaoReprogramada',{reviewId:row.id,dueAt:date});res.json(db.prepare('SELECT * FROM reviews WHERE id=?').get(row.id))}));

app.get('/api/flashcards',asyncRoute(async(req,res)=>{const dueOnly=req.query.due==='true',subjectId=Number(req.query.subjectId)||null;let sql=`SELECT f.*,s.name subject_name,m.name material_name FROM flashcards f LEFT JOIN subjects s ON s.id=f.subject_id LEFT JOIN materials m ON m.id=f.material_id WHERE f.space_id=?`;const args=[req.space.id];if(dueOnly){sql+=' AND (f.due_at IS NULL OR date(f.due_at)<=date(?))';args.push(toISODate())}if(subjectId){sql+=' AND f.subject_id=?';args.push(subjectId)}sql+=' ORDER BY COALESCE(f.due_at,\'1900-01-01\'),f.created_at DESC';res.json(db.prepare(sql).all(...args))}));
app.post('/api/flashcards',asyncRoute(async(req,res)=>{const front=requireString(req.body.front,'Frente',1,2000),back=requireString(req.body.back,'Verso',1,5000),subjectId=Number(req.body.subjectId)||null;if(subjectId)ensureSubject(req.space.id,subjectId);const id=db.prepare('INSERT INTO flashcards(space_id,subject_id,front,back,due_at) VALUES(?,?,?,?,?)').run(req.space.id,subjectId,front,back,toISODate()).lastInsertRowid;res.status(201).json(db.prepare('SELECT * FROM flashcards WHERE id=?').get(id))}));
app.post('/api/flashcards/generate',aiLimiter,asyncRoute(async(req,res)=>{const subject=ensureSubject(req.space.id,req.body.subjectId);const materials=selectedIds(req.body.materialIds);if(!materials.length)throw fail(400,'Escolha as fontes dos flashcards.');const count=Math.max(2,Math.min(40,Number(req.body.quantity)||12));const hits=sourceHits(req.space.id,materials,`${subject.name} conceitos flashcards`);const prompt=`Crie ${count} flashcards de recuperação ativa em português brasileiro, com perguntas curtas e respostas diretas, só com as fontes. Cite as fontes no campo citation. Responda JSON estrito {"cards":[{"front":"...","back":"...","citation":"S1"}]}.\nFONTES:\n${contextBlock(hits)}`;const result=parseJsonOutput(await generate(prompt,{maxOutputTokens:Math.min(5000,count*120)}));const cards=Array.isArray(result)?result:result.cards||[];const ids=[];transaction(()=>{for(const c of cards.slice(0,count)){if(!c.front||!c.back)continue;const hit=hits.find(h=>h.citation===c.citation)||hits[0];const id=db.prepare('INSERT INTO flashcards(space_id,subject_id,material_id,front,back,source_chunk_id,due_at) VALUES(?,?,?,?,?,?,?)').run(req.space.id,subject.id,hit.material_id,String(c.front).slice(0,2000),String(c.back).slice(0,5000),hit.chunk_id,toISODate()).lastInsertRowid;ids.push(id)}if(!ids.length)throw fail(502,'A IA não retornou flashcards utilizáveis.')});res.status(201).json({cards:ids.map(id=>db.prepare('SELECT * FROM flashcards WHERE id=?').get(id)),sources:visibleSources(hits)})}));
app.patch('/api/flashcards/:id',asyncRoute(async(req,res)=>{const card=rowInSpace('flashcards',req.params.id,req.space.id);if(!card)throw fail(404,'Flashcard não encontrado.');db.prepare('UPDATE flashcards SET front=?,back=?,subject_id=? WHERE id=?').run(req.body.front===undefined?card.front:requireString(req.body.front,'Frente',1,2000),req.body.back===undefined?card.back:requireString(req.body.back,'Verso',1,5000),req.body.subjectId===undefined?card.subject_id:(Number(req.body.subjectId)||null),card.id);res.json(db.prepare('SELECT * FROM flashcards WHERE id=?').get(card.id))}));
app.delete('/api/flashcards/:id',asyncRoute(async(req,res)=>{const card=rowInSpace('flashcards',req.params.id,req.space.id);if(!card)throw fail(404,'Flashcard não encontrado.');db.prepare('DELETE FROM flashcards WHERE id=?').run(card.id);res.json({ok:true})}));
app.post('/api/flashcards/:id/review',asyncRoute(async(req,res)=>{const card=rowInSpace('flashcards',req.params.id,req.space.id);if(!card)throw fail(404,'Flashcard não encontrado.');const quality=Math.max(0,Math.min(5,Number(req.body.quality)));if(!Number.isInteger(quality))throw fail(400,'Informe uma avaliação entre 0 e 5.');let ease=card.ease,interval=card.interval_days,reps=card.repetitions;if(quality<3){reps=0;interval=1}else{reps++;interval=reps===1?1:reps===2?6:Math.round(Math.max(1,interval)*ease);ease=Math.max(1.3,ease+(0.1-(5-quality)*(0.08+(5-quality)*0.02)))}const due=addDays(toISODate(),interval);db.prepare('UPDATE flashcards SET ease=?,interval_days=?,repetitions=?,due_at=? WHERE id=?').run(ease,interval,reps,due,card.id);if(card.subject_id){const s=ensureSubject(req.space.id,card.subject_id),score=quality/5,mastery=Math.max(0,Math.min(1,Number(s.mastery)*.85+score*.15));db.prepare('UPDATE subjects SET mastery=?,status=? WHERE id=?').run(mastery,mastery>=.85?'mastered':'learning',s.id)}logFor(req,'FlashcardRevisado',{flashcardId:card.id,quality,dueAt:due});res.json({card:db.prepare('SELECT * FROM flashcards WHERE id=?').get(card.id),intervalDays:interval})}));

app.get('/api/preferences',asyncRoute(async(req,res)=>res.json(db.prepare('SELECT * FROM preferences WHERE space_id=?').get(req.space.id))));
app.patch('/api/preferences',asyncRoute(async(req,res)=>{const p=db.prepare('SELECT * FROM preferences WHERE space_id=?').get(req.space.id);const daily=Math.max(15,Math.min(600,Number(req.body.dailyMinutes)||p.daily_minutes));const weekly=Math.max(daily,Math.min(3000,Number(req.body.weeklyMinutes)||p.weekly_minutes));const days=Array.isArray(req.body.availableDays)?req.body.availableDays.map(Number).filter(x=>Number.isInteger(x)&&x>=0&&x<=6):JSON.parse(p.available_days);if(!days.length)throw fail(400,'Selecione ao menos um dia disponível.');const start=/^([01]\d|2[0-3]):[0-5]\d$/.test(req.body.preferredStart)?req.body.preferredStart:p.preferred_start;db.prepare('UPDATE preferences SET daily_minutes=?,weekly_minutes=?,available_days=?,preferred_start=?,notifications=?,updated_at=CURRENT_TIMESTAMP WHERE space_id=?').run(daily,weekly,JSON.stringify([...new Set(days)]),start,req.body.notifications===undefined?p.notifications:(req.body.notifications?1:0),req.space.id);res.json(db.prepare('SELECT * FROM preferences WHERE space_id=?').get(req.space.id))}));
app.get('/api/plans',asyncRoute(async(req,res)=>{const weekStart=req.query.weekStart||mondayOf();if(!/^\d{4}-\d{2}-\d{2}$/.test(weekStart))throw fail(400,'Semana inválida.');res.json(planForSpace(req.space.id,weekStart))}));
app.post('/api/plans/generate',asyncRoute(async(req,res)=>{const weekStart=req.body.weekStart||mondayOf();const prefs=db.prepare('SELECT * FROM preferences WHERE space_id=?').get(req.space.id);const target=Number(req.body.targetMinutes)||prefs.weekly_minutes;rebuildPlan(req.space.id,weekStart,target);res.json(planForSpace(req.space.id,weekStart))}));
app.patch('/api/plan-items/:id',asyncRoute(async(req,res)=>{const item=rowInSpace('plan_items',req.params.id,req.space.id);if(!item)throw fail(404,'Atividade não encontrada.');const status=['planned','done','skipped'].includes(req.body.status)?req.body.status:item.status;const date=/^\d{4}-\d{2}-\d{2}$/.test(req.body.scheduledFor||'')?req.body.scheduledFor:item.scheduled_for;const minutes=req.body.estimatedMinutes===undefined?item.estimated_minutes:Math.max(5,Math.min(240,Number(req.body.estimatedMinutes)||30));transaction(()=>{db.prepare('UPDATE plan_items SET status=?,scheduled_for=?,estimated_minutes=?,completed_at=? WHERE id=?').run(status,date,minutes,status==='done'?new Date().toISOString():null,item.id);if(item.review_id&&status==='done'){db.prepare("UPDATE reviews SET status='completed',completed_at=? WHERE id=?").run(new Date().toISOString(),item.review_id);logFor(req,'RevisaoConcluida',{reviewId:item.review_id,markedWithoutQuiz:true})}else if(item.kind==='new'&&status==='done'&&item.subject_id){const subject=ensureSubject(req.space.id,item.subject_id);db.prepare("UPDATE subjects SET status='learning' WHERE id=? AND status='new'").run(subject.id);const now=new Date(),started=toISODate(now);const sessionId=db.prepare("INSERT INTO study_sessions(space_id,subject_id,session_type,started_at,completed_at,duration_minutes) VALUES(?,?,?,?,?,?)").run(req.space.id,subject.id,'initial',now.toISOString(),now.toISOString(),minutes).lastInsertRowid;let cycle=db.prepare("SELECT id FROM review_cycles WHERE space_id=? AND subject_id=? AND status='active' ORDER BY id DESC LIMIT 1").get(req.space.id,subject.id);if(!cycle){const cycleId=db.prepare('INSERT INTO review_cycles(space_id,subject_id,study_session_id,started_at) VALUES(?,?,?,?)').run(req.space.id,subject.id,sessionId,started).lastInsertRowid;[7,14,21,30].forEach((days,index)=>db.prepare('INSERT INTO reviews(cycle_id,space_id,subject_id,stage,due_at) VALUES(?,?,?,?,?)').run(cycleId,req.space.id,subject.id,index+1,addDays(started,days)));logFor(req,'AssuntoConcluido',{subjectId:subject.id,cycleId,source:'plan'})}}});if(status==='done')rebuildPlan(req.space.id,mondayOf());res.json(db.prepare('SELECT * FROM plan_items WHERE id=?').get(item.id))}));

function dashboardData(spaceId){const today=toISODate(),week=mondayOf();const due=db.prepare("SELECT COUNT(*) n FROM reviews WHERE space_id=? AND status IN ('scheduled','overdue') AND due_at<=?").get(spaceId,today).n;const subjectCount=db.prepare("SELECT COUNT(*) n FROM subjects WHERE space_id=? AND status!='archived'").get(spaceId).n;const mastered=db.prepare("SELECT COUNT(*) n FROM subjects WHERE space_id=? AND status='mastered'").get(spaceId).n;const q=db.prepare('SELECT COUNT(*) total,COALESCE(SUM(is_correct),0) correct,COALESCE(AVG(score),0) accuracy FROM attempts WHERE space_id=? AND attempted_at>=?').get(spaceId,addDays(today,-30));const mins=db.prepare('SELECT COALESCE(SUM(duration_minutes),0) n FROM study_sessions WHERE space_id=? AND completed_at>=?').get(spaceId,addDays(today,-7)).n;const dueSoon=db.prepare("SELECT r.id,r.due_at,r.stage,r.status,s.name subject_name FROM reviews r JOIN subjects s ON s.id=r.subject_id WHERE r.space_id=? AND r.status IN ('scheduled','overdue') ORDER BY r.due_at LIMIT 6").all(spaceId);const plan=planForSpace(spaceId);const todayItems=plan.items.filter(i=>i.scheduled_for===today);const weeklyMinutes=db.prepare('SELECT weekly_minutes FROM preferences WHERE space_id=?').get(spaceId)?.weekly_minutes||450;const recent=db.prepare('SELECT id,name,mime_type,process_status,created_at FROM materials WHERE space_id=? ORDER BY created_at DESC LIMIT 5').all(spaceId);const sessions=db.prepare(`SELECT ss.*,s.name subject_name FROM study_sessions ss LEFT JOIN subjects s ON s.id=ss.subject_id WHERE ss.space_id=? AND ss.completed_at IS NOT NULL ORDER BY ss.completed_at DESC LIMIT 6`).all(spaceId);return {today,weekStart:week,reviewDue:due,subjectCount,mastered,questions: q.total,accuracy:Number(q.accuracy)||0,weeklyMinutes:Number(mins)||0,weeklyGoal:weeklyMinutes,dueSoon,plan:todayItems,planTotal:todayItems.reduce((n,i)=>n+i.estimated_minutes,0),recent,activity:sessions}};
app.get('/api/dashboard',asyncRoute(async(req,res)=>res.json(dashboardData(req.space.id))));
app.get('/api/performance',asyncRoute(async(req,res)=>{const summary=db.prepare('SELECT COUNT(*) questions,COALESCE(SUM(is_correct),0) correct,COALESCE(AVG(score),0) accuracy,COALESCE(SUM(duration_seconds),0) answer_seconds FROM attempts WHERE space_id=?').get(req.space.id);const bySubject=db.prepare(`SELECT s.id,s.name,s.mastery,s.status,COUNT(a.id) attempts,COALESCE(AVG(a.score),0) accuracy,COALESCE(SUM(a.is_correct),0) correct,MAX(a.attempted_at) last_attempt FROM subjects s LEFT JOIN attempts a ON a.subject_id=s.id WHERE s.space_id=? AND s.status!='archived' GROUP BY s.id ORDER BY s.mastery ASC,s.priority`).all(req.space.id);const sessions=db.prepare(`SELECT date(completed_at) day,COUNT(*) sessions,COALESCE(SUM(duration_minutes),0) minutes,COALESCE(SUM(questions_correct),0) correct,COALESCE(SUM(questions_total),0) questions FROM study_sessions WHERE space_id=? AND completed_at IS NOT NULL AND date(completed_at)>=date(?) GROUP BY date(completed_at) ORDER BY day`).all(req.space.id,addDays(toISODate(),-55));const reviews=db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) completed,SUM(CASE WHEN status IN ('scheduled','overdue') AND due_at<? THEN 1 ELSE 0 END) overdue FROM reviews WHERE space_id=?").get(toISODate(),req.space.id);res.json({summary:{...summary,accuracy:Number(summary.accuracy)||0},subjects:bySubject,sessions,reviews})}));
app.get('/api/attempts',asyncRoute(async(req,res)=>{const rows=db.prepare(`SELECT a.*,q.prompt,s.name subject_name FROM attempts a LEFT JOIN questions q ON q.id=a.question_id LEFT JOIN subjects s ON s.id=a.subject_id WHERE a.space_id=? ORDER BY a.attempted_at DESC LIMIT 200`).all(req.space.id);res.json(rows.map(r=>({...r,answer:JSON.parse(r.answer_json)})))}));

app.patch('/api/profile',asyncRoute(async(req,res)=>{const name=req.body.name===undefined?req.user.name:requireString(req.body.name,'Nome',2,80);const email=req.body.email===undefined?req.user.email:normalizeEmail(req.body.email);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw fail(400,'Informe um e-mail válido.');if(email!==req.user.email&&db.prepare('SELECT id FROM users WHERE email=?').get(email))throw fail(409,'E-mail já está cadastrado.');db.prepare('UPDATE users SET name=?,email=? WHERE id=?').run(name,email,req.user.id);res.json(safeUser(db.prepare('SELECT * FROM users WHERE id=?').get(req.user.id)))}));
app.post('/api/profile/password',asyncRoute(async(req,res)=>{const record=db.prepare('SELECT * FROM users WHERE id=?').get(req.user.id);if(!verifyPassword(String(req.body.currentPassword||''),record.password_hash))throw fail(401,'A senha atual está incorreta.');const next=String(req.body.newPassword||'');if(next.length<10||next.length>200)throw fail(400,'A nova senha precisa ter pelo menos 10 caracteres.');db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(passwordHash(next),req.user.id);res.json({ok:true})}));
app.get('/api/account/export',asyncRoute(async(req,res)=>{const spaceIds=db.prepare('SELECT id FROM spaces WHERE user_id=?').all(req.user.id).map(r=>r.id);const data={exportedAt:new Date().toISOString(),user:safeUser(req.user),spaces:db.prepare('SELECT * FROM spaces WHERE user_id=?').all(req.user.id)};for(const table of ['notebooks','subjects','generated_materials','generated_material_versions','generated_sources','questions','question_sources','attempts','flashcards','study_sessions','session_questions','review_cycles','reviews','plans','plan_items','preferences','domain_events']){data[table]=[];for(const id of spaceIds){if(table==='generated_material_versions')data[table].push(...db.prepare('SELECT v.* FROM generated_material_versions v JOIN generated_materials g ON g.id=v.generated_material_id WHERE g.space_id=?').all(id));else if(table==='generated_sources')data[table].push(...db.prepare('SELECT gs.* FROM generated_sources gs JOIN generated_materials g ON g.id=gs.generated_material_id WHERE g.space_id=?').all(id));else if(table==='question_sources')data[table].push(...db.prepare('SELECT qs.* FROM question_sources qs JOIN questions q ON q.id=qs.question_id WHERE q.space_id=?').all(id));else if(table==='session_questions')data[table].push(...db.prepare('SELECT sq.* FROM session_questions sq JOIN study_sessions ss ON ss.id=sq.session_id WHERE ss.space_id=?').all(id));else data[table].push(...db.prepare(`SELECT * FROM ${table} WHERE space_id=?`).all(id))}}data.materials=[];data.material_chunks=[];data.material_versions=[];for(const id of spaceIds){data.materials.push(...db.prepare('SELECT id,space_id,subject_id,notebook_id,name,original_name,mime_type,file_size,source_url,version,process_status,process_error,extracted_text,created_at,updated_at FROM materials WHERE space_id=?').all(id));data.material_chunks.push(...db.prepare('SELECT c.* FROM material_chunks c JOIN materials m ON m.id=c.material_id WHERE m.space_id=?').all(id));data.material_versions.push(...db.prepare('SELECT v.id,v.material_id,v.version,v.original_name,v.mime_type,v.file_size,v.process_status,v.process_error,v.extracted_text,v.created_at FROM material_versions v JOIN materials m ON m.id=v.material_id WHERE m.space_id=?').all(id))}res.setHeader('Content-Type','application/json');res.setHeader('Content-Disposition','attachment; filename="study-space-export.json"');res.send(JSON.stringify(data,null,2))}));
app.delete('/api/account',asyncRoute(async(req,res)=>{const record=db.prepare('SELECT * FROM users WHERE id=?').get(req.user.id);if(!verifyPassword(String(req.body.password||''),record.password_hash))throw fail(401,'Confirme sua senha para excluir a conta.');const spaceIds=db.prepare('SELECT id FROM spaces WHERE user_id=?').all(req.user.id).map(r=>r.id);const files=[];for(const id of spaceIds){files.push(...db.prepare('SELECT file_path FROM materials WHERE space_id=?').all(id).map(r=>r.file_path));files.push(...db.prepare('SELECT v.file_path FROM material_versions v JOIN materials m ON m.id=v.material_id WHERE m.space_id=?').all(id).map(r=>r.file_path))}db.prepare('DELETE FROM users WHERE id=?').run(req.user.id);for(const rel of files)await fsp.rm(path.resolve(root,rel),{force:true});res.clearCookie('study_session',{httpOnly:true,sameSite:'lax',secure:Boolean(req.secure),path:'/'}).json({ok:true})}));

app.use('/api',(_req,_res,next)=>next(fail(404,'Rota de API não encontrada.')));
app.use((error,req,res,next)=>{if(error instanceof multer.MulterError){const status=error.code==='LIMIT_FILE_SIZE'?413:400;return res.status(status).json({error:error.code==='LIMIT_FILE_SIZE'?'O arquivo excede o limite de 25 MB.':error.message})}if(error.status){return res.status(error.status).json({error:error.message,code:error.code})}console.error(error);res.status(500).json({error:'Ocorreu um erro interno. Tente novamente.'})});
app.get('/{*splat}',(req,res)=>res.sendFile(path.join(root,'public','index.html')));

const server=app.listen(port,()=>{console.log(`Study Space disponível em http://localhost:${port}`);recoverJobs()});
const shutdown=()=>server.close(()=>process.exit(0));process.on('SIGINT',shutdown);process.on('SIGTERM',shutdown);
